// client-ordering · снимок и восстановление серверной корзины buyer («test»).
// Корзина общая для всех прогонов и ручных сессий: тесты, которые её меняют (@data), снимают её до начала
// и в конце возвращают как было (те же товары и количества). Источник снимка — ответ GET /rest/v1/cart_items на /shop/cart.
import { test, expect, Page, Browser } from '@playwright/test';
import { auth, emptyCart } from '../orders/_qa-order';

export type CartLine = { product_id: string; qty: number };

const isCartGet = (url: string, method: string) => url.includes('/rest/v1/cart_items') && method === 'GET';

/** Текущее содержимое корзины buyer: [{product_id, qty}]. */
export async function cartSnapshot(page: Page): Promise<CartLine[]> {
  const resp = page.waitForResponse((r) => isCartGet(r.url(), r.request().method()) && r.ok(), { timeout: 30_000 });
  await page.goto('/shop/cart');
  const rows = (await (await resp).json()) as CartLine[];
  await expect(page.getByRole('heading', { name: 'העגלה שלי' })).toBeVisible({ timeout: 30_000 });
  return rows.map((r) => ({ product_id: r.product_id, qty: Number(r.qty) }));
}

/** Вернуть корзину к снимку: очистить, добавить товары со страниц /shop/p/<id>, выставить количества. */
export async function restoreCart(page: Page, snap: CartLine[]) {
  await emptyCart(page);
  const names = new Map<string, string>();
  const skipped: string[] = [];
  for (const line of snap) {
    await page.goto(`/shop/p/${line.product_id}`);
    const h1 = page.getByRole('heading', { level: 1 });
    await expect(h1).toBeVisible({ timeout: 30_000 });
    const name = (await h1.innerText()).trim();
    const add = page.getByRole('button', { name: /^הוסף לעגלה/ });
    if (!(await add.count()) || !(await add.isEnabled())) { skipped.push(name); continue; }
    names.set(line.product_id, name);
    const added = page.waitForResponse((r) => r.url().includes('cart_set_item'));
    await add.click();
    await added;
  }
  const now = new Map((await cartSnapshot(page)).map((l) => [l.product_id, l.qty]));
  for (const line of snap) {
    const name = names.get(line.product_id);
    if (!name) continue;
    let diff = line.qty - (now.get(line.product_id) ?? 0);
    const btn = page.getByRole('button', { name: `${diff > 0 ? 'הוספת' : 'הפחתת'} יחידה — ${name}` });
    for (; diff !== 0; diff += diff > 0 ? -1 : 1) {
      if (!(await btn.isEnabled())) { skipped.push(`${name} (qty)`); break; }
      const resp = page.waitForResponse((r) => r.url().includes('cart_set_item'));
      await btn.click();
      await resp;
    }
  }
  if (skipped.length) {
    test.info().annotations.push({ type: 'cart-restore', description: `не восстановлено (нет в наличии/недоступно): ${skipped.join(', ')}` });
  }
}

/** То же в отдельном окне buyer (для afterAll). */
export async function restoreCartIn(browser: Browser, snap: CartLine[] | undefined) {
  if (!snap) return;
  const ctx = await browser.newContext({ storageState: auth('buyer'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
  try {
    await restoreCart(await ctx.newPage(), snap);
  } finally {
    await ctx.close();
  }
}
